// Regenerates src/lib/airports-data.ts from the airports CSV.
//   node scripts/gen-airports.mjs ../../data/airports.csv
// The CSV (data/ is git-ignored) has IATA_CODE, ..., LATITUDE, LONGITUDE. Only
// the code and position are kept, so the generated file stays small and the
// app needs no data fetch at run time.
import { readFileSync, writeFileSync } from "node:fs";

const input = process.argv[2];
if (!input) {
  console.error("usage: node scripts/gen-airports.mjs <airports.csv>");
  process.exit(1);
}

/** Splits one CSV line, honouring double-quoted fields. */
function cells(line) {
  const out = [];
  let cur = "";
  let quoted = false;
  for (const ch of line) {
    if (ch === '"') quoted = !quoted;
    else if (ch === "," && !quoted) {
      out.push(cur);
      cur = "";
    } else cur += ch;
  }
  out.push(cur);
  return out;
}

const [head, ...lines] = readFileSync(input, "utf8").split(/\r?\n/).filter(Boolean);
const cols = cells(head);
const [iCode, iLat, iLon] = ["IATA_CODE", "LATITUDE", "LONGITUDE"].map((c) => cols.indexOf(c));
if ([iCode, iLat, iLon].includes(-1)) throw new Error(`Missing column in: ${head}`);

const rows = [];
for (const line of lines) {
  const c = cells(line);
  const lat = Number.parseFloat(c[iLat]);
  const lon = Number.parseFloat(c[iLon]);
  if (!c[iCode] || Number.isNaN(lat) || Number.isNaN(lon)) continue;
  rows.push([c[iCode].trim(), Math.round(lat * 1000) / 1000, Math.round(lon * 1000) / 1000]);
}
rows.sort((a, b) => a[0].localeCompare(b[0]));

const body = rows.map(([code, lat, lon]) => `${code}:[${lat},${lon}]`).join(",");
writeFileSync(
  new URL("../src/lib/airports-data.ts", import.meta.url),
  `// Generated by scripts/gen-airports.mjs from data/airports.csv. Do not edit.\n` +
    `/** IATA code to [latitude, longitude]. */\n` +
    `export const AIRPORT_POSITIONS: Record<string, [number, number]> = {${body}};\n`,
);
console.log(`wrote ${rows.length} airports`);
